const items = $input.all();

// Validar si la entrada está vacía o si Pinecone no devolvió datos válidos
if (!items || items.length === 0 || !items[0].json) {
  return [{ json: { context: 'No se encontró material relevante sobre el tema en la base de datos.', citations: [] } }];
}

const sources = items.map(function(i) {
  const doc = i.json.document || i.json;
  const text = doc.pageContent || doc.text || i.json.pageContent || i.json.text || '';
  const metadata = doc.metadata || i.json.metadata || {};

  return {
    text: text,
    source: metadata.archivo || metadata.filename || metadata.source || 'Material del curso',
    page: metadata.pagina || metadata.page || null
  };
}).filter(function(s) { 
  return typeof s.text === 'string' && s.text.trim().length > 0; 
});

// Fallback seguro si tras filtrar no hay texto extraíble
if (sources.length === 0) {
  return [{ json: { context: 'No se encontró material relevante sobre el tema en la base de datos.', citations: [] } }];
}

const formattedText = sources.map(function(s, idx) {
  const pageInfo = s.page ? ' (Pág. ' + s.page + ')' : '';
  return '[' + (idx + 1) + '] Fuente: ' + s.source + pageInfo + '\n' + s.text;
}).join('\n\n---\n\n');

const citations = sources.map(function(s) {
  return { archivo: s.source, pagina: s.page };
});

return [{ json: { context: formattedText, citations: citations } }];
